            r = f.result()
            if r is None:
                self.node.log('ERROR', f'{what}: 응답 없음')
            elif not r.success:
                self.node.log('WARN', f'{what}: {r.message}')
            elif log_ok:
                self.node.log('INFO', f'{what}: {r.message}')
        fut.add_done_callback(done)
        return True

