  std::strftime(buf, sizeof(buf), "%H:%M:%S", std::localtime(&t));
  return buf;
}

// rcl_interfaces/Log 수준 숫자 -> 글자
std::string levelName(uint8_t l)
{
  switch (l) {
    case 10: return "DEBUG";
    case 20: return "INFO";
    case 30: return "WARN";
