// ARIS 공용 위젯.
//   Panel      : 붉은 제목줄 + 금속 판 + 그림자 (목업의 패널)
//   CameraView : 카메라 영상 + 픽셀 검출 상자 + HUD 모서리 (M2 에서 TF 투영·클릭 선택을 더함)
//   LogoBadge  : ARIS 엠블럼 + 글자 (상단 줄 가운데)
#pragma once

#include <QFrame>
#include <QImage>
#include <QLabel>
#include <QVBoxLayout>
