#include <vector>

#include "aris3_interfaces/msg/detected_object.hpp"

namespace aris
{

class Panel : public QFrame
{
  Q_OBJECT

public:
  // title: 제목줄 글자 (예: "SYSTEM STATUS  시스템 상태")
