QWidget * MainWindow::buildPlaceholder(const QString & title, const QString & text)
{
  auto * p = new Panel(title);
  auto * l = new QLabel(text);
  l->setWordWrap(true);
  l->setAlignment(Qt::AlignCenter);
  l->setStyleSheet("color:#9aa7b4");
