("""}  // namespace aris""","""// 3차원 벡터·쿼터니언 (x, y, z, w)
using Vec3 = std::array<double, 3>;
using Quat = std::array<double, 4>;

// 쿼터니언 q 로 벡터 v 회전
Vec3 quatApply(const Quat & q, const Vec3 & v);

// 바늘구멍 카메라: world -> 카메라 광학 좌표 변환(TF lookup_transform(camera_frame, "world"))과 수평 화각.
// 광학 좌표: z = 앞(광축), x = 영상 오른쪽, y = 영상 아래 (ROS 광학 프레임 규약)
struct PinholeCamera
{
  Vec3 t{0, 0, 0};        // 변환의 이동
  Quat q{0, 0, 0, 1};     // 변환의 회전
  double hfov{1.4};       // 수평 화각 [rad]
  int width{640}, height{480};

  double focal() const;   // 픽셀 단위 초점 거리
  // world 점 -> (u, v, 깊이). 카메라 뒤면 없음
  std::optional<Vec3> project(const Vec3 & p) const;
  // 영상 픽셀 -> world 평면 z = plane_z 위의 (x, y). 평면과 만나지 않으면 없음
  std::optional<std::array<double, 2>> unproject(double u, double v, double plane_z) const;
};

}  // namespace aris"""),
])
edit('src/gui_logic.cpp', [
("""#include <algorithm>
""","""#include <algorithm>
#include <cmath>
"""),
("""}  // namespace aris""","""Vec3 quatApply(const Quat & q, const Vec3 & v)
{
  // v' = v + w t + q_vec x t,  t = 2 (q_vec x v)  (aris3_gui widgets.quat_apply 와 같음)
  const double x = q[0], y = q[1], z = q[2], w = q[3];
  const double tx = 2 * (y * v[2] - z * v[1]);
  const double ty = 2 * (z * v[0] - x * v[2]);
  const double tz = 2 * (x * v[1] - y * v[0]);
  return {v[0] + w * tx + (y * tz - z * ty), v[1] + w * ty + (z * tx - x * tz), v[2] + w * tz + (x * ty - y * tx)};
}

double PinholeCamera::focal() const
{
  return (width / 2.0) / std::tan(hfov / 2.0);
}

std::optional<Vec3> PinholeCamera::project(const Vec3 & p) const
{
  Vec3 c = quatApply(q, p);
  c = {c[0] + t[0], c[1] + t[1], c[2] + t[2]};
  if (c[2] <= 0.01) {return std::nullopt;}           // 카메라 뒤 또는 너무 가까움
  const double f = focal();
  return Vec3{width / 2.0 + f * c[0] / c[2], height / 2.0 + f * c[1] / c[2], c[2]};
}

std::optional<std::array<double, 2>> PinholeCamera::unproject(double u, double v, double plane_z) const
{
  const Quat qi{-q[0], -q[1], -q[2], q[3]};          // world <- 카메라 회전
  const double f = focal();
  const Vec3 d = quatApply(qi, {(u - width / 2.0) / f, (v - height / 2.0) / f, 1.0});   // 광선 방향 (world)
  const Vec3 o = quatApply(qi, {-t[0], -t[1], -t[2]});                                // 카메라 중심 (world)
  if (std::abs(d[2]) < 1e-9) {return std::nullopt;}
  const double s = (plane_z - o[2]) / d[2];
  if (s <= 0) {return std::nullopt;}
  return std::array<double, 2>{o[0] + s * d[0], o[1] + s * d[1]};
}

}  // namespace aris"""),
])
s=open('test/test_gui_logic.cpp').read()
s+='''
// 아래를 보는 카메라 (world (0, 0, 2) 에서 -z 방향): 영상 가운데 = 바로 아래, project 와 unproject 가 서로 반대.
TEST(PinholeCamera, ProjectUnprojectRoundTrip)
{
  aris::PinholeCamera cam;
  // world -> 광학: x 축으로 180° 회전 (z 가 아래를 봄) 후 카메라 높이 2 m 만큼 앞(광축)으로
  cam.q = {1.0, 0.0, 0.0, 0.0};
  cam.t = {0.0, 0.0, 2.0};
  cam.width = 640;
  cam.height = 480;
  cam.hfov = 1.4;
  const auto c = cam.project({0.0, 0.0, 0.0});
  ASSERT_TRUE(c.has_value());
  EXPECT_NEAR((*c)[0], 320.0, 1e-9);
  EXPECT_NEAR((*c)[1], 240.0, 1e-9);
  EXPECT_NEAR((*c)[2], 2.0, 1e-9);
  const auto p = cam.project({0.3, -0.2, 0.75});
  ASSERT_TRUE(p.has_value());
  const auto back = cam.unproject((*p)[0], (*p)[1], 0.75);
  ASSERT_TRUE(back.has_value());
  EXPECT_NEAR((*back)[0], 0.3, 1e-9);
  EXPECT_NEAR((*back)[1], -0.2, 1e-9);
  EXPECT_FALSE(cam.project({0.0, 0.0, 3.0}).has_value());     // 카메라 뒤(위)는 없음
}

// 쿼터니언 회전: z 축 90° 회전이면 x 축이 y 축으로.
TEST(PinholeCamera, QuatApplyRotatesVector)
{
  const double s = std::sqrt(0.5);
  const auto r = aris::quatApply({0.0, 0.0, s, s}, {1.0, 0.0, 0.0});
  EXPECT_NEAR(r[0], 0.0, 1e-12);
  EXPECT_NEAR(r[1], 1.0, 1e-12);
  EXPECT_NEAR(r[2], 0.0, 1e-12);
}
'''
s=s.replace('#include <gtest/gtest.h>\n','#include <gtest/gtest.h>\n\n#include <cmath>\n')
open('test/test_gui_logic.cpp','w').write(s)
EOF
