    std::snprintf(buf, sizeof(buf), "선택(저기): 놓을 자리 (%.3f, %.3f)", x, y);
    node_->log("INFO", std::string(buf) + (sel_id_.empty() ? "  → 옮길 큐브를 클릭하거나 「아리스 파란 큐브 저기로」" :
