bool alive(qint64 pid)
{
  if (pid <= 0) {return false;}
  int status = 0;
  if (::waitpid(static_cast<pid_t>(pid), &status, WNOHANG) == static_cast<pid_t>(pid)) {return false;}
  return ::kill(static_cast<pid_t>(pid), 0) == 0;
}
}  // namespace

