{
  if (!armOk("고른 자리에 놓기")) {return;}
  if (real_->pickRunning()) {
    node_->log("WARN", "고른 자리에 놓기: 이전 순서가 진행 중");
    return;
  }
  if (!real_->calibReady()) {
    node_->log("WARN", "고른 자리에 놓기: 카메라 보정이 없음 (점 4개 이상 기록)");
    return;
