  const std::string c = colorKo(color);
  if (c.empty() && it == k.end()) {return "고르신 물체";}
  const std::string s = it == k.end() ? std::string("큐브") : it->second;   // 작업 공간의 물체는 큐브
  return c.empty() ? s : c + " " + s;
