  } else if (name == "burgundy") {           // 버건디 + 샴페인 골드: 차분하고 고급스럽게
    v = {{345, 0.75, 0.75}, {40, 0.55, 0.95}, {190, 0.6, 0.9}};
  } else if (name == "carbon") {             // 카본 블랙 + 골드: 검은 장갑판에 금색만 강조
    v = {{0, 0.12, 0.55}, {45, 1.1, 1.0}, {190, 1.0, 1.0}};
  } else if (name == "silver") {             // 마크 2 실버: 강철판 + 은색 테두리 + 청록
    v = {{215, 0.18, 1.35}, {210, 0.08, 1.05}, {190, 1.0, 1.0}};
  } else {
    return qss;                              // classic: 마크 3 빨강·금색·청록 그대로
  }
  QString out = qss;
  static const QRegularExpression re("#[0-9a-fA-F]{6}");
  auto it = re.globalMatch(qss);
  QSet<QString> seen;
  while (it.hasNext()) {
    const QString hex = it.next().captured(0).toLower();
    if (seen.contains(hex) || keepColors().contains(hex)) {continue;}
    seen.insert(hex);
    out.replace(hex, recolor(QColor(hex), v).name(), Qt::CaseInsensitive);
  }
  return out;
}
}  // namespace

