// ARIS 테마 구현 (theme.hpp 설명 참고). Qt 스타일시트는 그림자를 못 그리므로 패널 그림자는
// widgets.cpp 의 Panel 이 QGraphicsDropShadowEffect 로 넣는다.
#include "aris3_gui_cpp/theme.hpp"

#include <QColor>
#include <QRegularExpression>
#include <QSet>
#include <QtGlobal>

#include <algorithm>
#include <cmath>

namespace aris::theme
{

namespace
{
// 테마 후보 (2026-11-12): 기본 QSS 의 색을 계열별(장갑판 빨강·금색 테두리·아크 청록)로 바꿔 만든다.
// 실행할 때 ARIS_THEME=classic|jarvis|burgundy|carbon|silver 로 고른다 (없으면 classic).
struct Tone
{
  int hue;        // 바꿀 색상 (0~359), -1 이면 원래 색상 그대로
  double sat;     // 채도 배율
  double val;     // 밝기 배율
};
struct Variant
{
  Tone armor, trim, glow;   // 빨강 계열, 금색 계열, 청록 계열
};

// 정지 버튼 색은 어느 테마에서도 그대로 (가장 눈에 띄어야 함)
const QSet<QString> & keepColors()
{
  static const QSet<QString> k{"#ff5a5f", "#d41b22", "#9e0f15", "#ffd23f", "#7a0a0f", "#ffffff"};
  return k;
}

// 한 색을 테마에 맞게: 채도가 낮은 색(글자 흰색 등)은 그대로, 나머지는 색상으로 계열을 나눈다
QColor recolor(const QColor & c, const Variant & v)
{
  int h, s, val, a;
  c.getHsv(&h, &s, &val, &a);
  if (s < 40 || h < 0) {return c;}
  const Tone * t = nullptr;
  if (h >= 160 && h <= 210) {
    t = &v.glow;
  } else if (h >= 30 && h <= 60) {
    t = &v.trim;
  } else if (h >= 330 || h <= 20) {
    t = &v.armor;
  } else {
    return c;
  }
  const int nh = t->hue < 0 ? h : t->hue;
  const int ns = std::clamp(static_cast<int>(std::lround(s * t->sat)), 0, 255);
  const int nv = std::clamp(static_cast<int>(std::lround(val * t->val)), 0, 255);
  return QColor::fromHsv(nh, ns, nv, a);
}

QString applyVariant(const QString & qss)
{
  const QByteArray name = qgetenv("ARIS_THEME");
  // 장갑판 / 금색 테두리 / 아크 청록
  Variant v;
  if (name == "jarvis") {                    // 자비스 HUD: 남색 유리 + 청록 테두리
    v = {{205, 0.75, 0.9}, {188, 0.75, 1.0}, {188, 1.0, 1.0}};
  } else if (name == "burgundy") {           // 버건디 + 샴페인 골드: 차분하고 고급스럽게
    v = {{345, 0.75, 0.75}, {40, 0.55, 0.95}, {190, 0.6, 0.9}};
  } else if (name == "carbon") {             // 카본 블랙 + 골드: 검은 장갑판에 금색만 강조
    v = {{0, 0.12, 0.55}, {45, 1.1, 1.0}, {190, 1.0, 1.0}};
  } else if (name == "silver") {             // 마크 2 실버: 강철판 + 은색 테두리 + 청록
    v = {{215, 0.18, 1.35}, {210, 0.08, 1.05}, {190, 1.0, 1.0}};
  } else {
    return qss;                              // classic: 마크 3 빨강·금색·청록 그대로
  }
  QString out = qss;
  static const QRegularExpression re("#[0-9a-fA-F]{6}");
  auto it = re.globalMatch(qss);
  QSet<QString> seen;
  while (it.hasNext()) {
    const QString hex = it.next().captured(0).toLower();
    if (seen.contains(hex) || keepColors().contains(hex)) {continue;}
    seen.insert(hex);
    out.replace(hex, recolor(QColor(hex), v).name(), Qt::CaseInsensitive);
  }
  return out;
}
