QPushButton { color: #f5d27a; font-weight: 600; padding: 6px 12px; border: 1px solid #c9a227; border-radius: 4px;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #7a151d, stop:0.5 #4c0c12, stop:1 #2a070a); }
QPushButton:hover { border-color: #5ff4ff; color: #ffe08a;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #9a1a23, stop:0.5 #5e0f16, stop:1 #33080c); }
QPushButton:pressed { background: #24060a; padding-top: 7px; padding-bottom: 5px; }
QPushButton:disabled { color: #6b5a4a; border-color: #4a3a20;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #2a1416, stop:1 #170b0c); }
/* 금색 강조 버튼 (선택한 물체를 그 자리로 등) */
QPushButton#gold { color: #3a0508; font-weight: 800; border: 1px solid #6b5014;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #fff0b3, stop:0.45 #f0c54a, stop:1 #a8801a); }
QPushButton#gold:hover { border-color: #5ff4ff; }
QPushButton#gold:disabled { color: #4a3a20; background: #3a2e10; }
QPushButton#gold:checked { border: 2px solid #5ff4ff; }
/* 음성 명령 버튼: 붉은 판 위 굵고 밝은 금색 글자 (선명하게). 켜지면 아크 리액터 청록 테두리 */
QPushButton#voice { color: #ffd54a; font-size: 12pt; font-weight: 800; letter-spacing: 1px; border: 2px solid #ffd54a;
  border-radius: 6px; background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #e0262f, stop:0.5 #9e131b, stop:1 #5e0b11); }
QPushButton#voice:hover { color: #fff0b3; border-color: #fff0b3; }
QPushButton#voice:checked { color: #fff0b3; border: 3px solid #5ff4ff;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #ff3b44, stop:0.5 #b3161f, stop:1 #6a0c12); }
QPushButton#voice:disabled { color: #8a7040; border-color: #6b5014; background: #3a0d10; }
/* 정지: 밝은 빨강 + 노란 굵은 테두리 - 무엇보다 눈에 띄게 (테마 빨강에 묻히지 않게) */
QPushButton#estop { color: white; font-weight: 800; font-size: 12pt; border: 3px solid #ffd23f; border-radius: 6px;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #ff5a5f, stop:0.55 #d41b22, stop:1 #9e0f15); }
QPushButton#estop:pressed { background: #7a0a0f; }

/* 입력칸·목록·표·로그: 자비스 HUD - 어두운 유리 + 청록 글자, 초점이 오면 청록 테두리 */
QLineEdit, QComboBox, QPlainTextEdit, QListWidget, QTableWidget,
QFrame#panel QLineEdit, QFrame#panel QComboBox, QFrame#panel QPlainTextEdit, QFrame#panel QListWidget,
QFrame#panel QTableWidget { background: #05090b; border: 1px solid #1f6f78;
  border-radius: 4px; color: #bff9ff; selection-background-color: #0f5560; selection-color: #ffffff; }
QLineEdit:focus, QComboBox:focus, QPlainTextEdit:focus { border: 1px solid #5ff4ff; }
QComboBox QAbstractItemView { background: #0a1114; color: #bff9ff; selection-background-color: #0f5560; }
QHeaderView::section { background: #6a0c12; color: #ffe08a; font-weight: 700; border: none; border-bottom: 2px solid #c9a227; padding: 3px; }
QTableWidget { gridline-color: #12343a; }

/* 탭 (TCP 이동 / Joint 이동): 붉은 판, 고른 탭은 금색 페이스플레이트 */
QTabWidget::pane { border: 1px solid #c9a227; border-radius: 4px; top: -1px; }
QTabBar::tab { color: #f5d27a; padding: 5px 14px; border: 1px solid #c9a227; border-bottom: none;
  border-top-left-radius: 4px; border-top-right-radius: 4px; margin-right: 2px;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #6e141b, stop:1 #2a070a); }
QTabBar::tab:selected { color: #3a0508; font-weight: 800;
  background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #fff0b3, stop:1 #c9971a); }

/* 체크박스: 금색 테두리, 켜면 아크 리액터 청록 */
QCheckBox { color: #f1e6dc; }
QCheckBox::indicator { width: 15px; height: 15px; border: 2px solid #d4a017; border-radius: 3px; background: #05090b; }
QCheckBox::indicator:checked { background: qradialgradient(cx:0.5, cy:0.5, radius:0.6, stop:0 #e6fdff, stop:0.5 #5ff4ff, stop:1 #0f8a96); }

/* 슬라이더 (속도): 지나온 길은 청록, 손잡이는 금색 */
QSlider::groove:horizontal { height: 6px; border-radius: 3px; background: #2a0a0d; border: 1px solid #4a3a20; }
QSlider::sub-page:horizontal { border-radius: 3px; background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #0f8a96, stop:1 #5ff4ff); }
QSlider::handle:horizontal { width: 14px; margin: -5px 0; border-radius: 7px; border: 1px solid #6b5014;
  background: qradialgradient(cx:0.4, cy:0.4, radius:0.7, stop:0 #fff0b3, stop:1 #c9971a); }

/* 진행 막대: 아크 리액터 청록 */
QProgressBar { border: 1px solid #c9a227; border-radius: 5px; background: #05090b; text-align: center; color: #f1e6dc; }
QProgressBar::chunk { border-radius: 4px; background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #bff9ff, stop:1 #13a7b5); }
QScrollBar:vertical { background: #05090b; width: 10px; }
QScrollBar::handle:vertical { background: #8a6d22; border-radius: 4px; }
)QSS"));
}

QString dot(bool ok, const QString & text, bool warn)
{
  if (ok) {
    return QStringLiteral("<span style='color:#5ff4ff'>●</span> %1").arg(text);
  }
  if (warn) {
    return QStringLiteral("<span style='color:#f2a33a'>●</span> <span style='color:#f2a33a'>%1</span>").arg(text);
  }
  return QStringLiteral("<span style='color:#ff4d4f'>⚠</span> <span style='color:#ff4d4f'>%1</span>").arg(text);
}

