  node_->say(!chk_arm_->isChecked() && v->action == "home" ? std::string("조작 허용을 먼저 켜 주세요.") :
    voiceReply(v->action, v->color, v->shape, v->refers_selected_place));
  if (v->action == "place") {
    node_->log("WARN", "「내려놔」(집은 자리에 놓기)는 Task Manager 의 pick/place 분리 후 지원 예정 - "
